import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"能力总览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/intro/features.md","filePath":"zh/intro/features.md","lastUpdated":1790683574000}'),o={name:"zh/intro/features.md"};function h(i,t,n,l,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="能力总览" tabindex="-1">能力总览 <a class="header-anchor" href="#能力总览" aria-label="Permalink to &quot;能力总览&quot;">​</a></h1><p>本页列出系统<strong>实际具备</strong>的功能模块。各模块是否对终端用户开放，由运营在后台的玩法配置中控制。</p><h2 id="交易" tabindex="-1">交易 <a class="header-anchor" href="#交易" aria-label="Permalink to &quot;交易&quot;">​</a></h2><table tabindex="0"><thead><tr><th>品类</th><th>说明</th></tr></thead><tbody><tr><td>现货</td><td>币币交易，限价与市价委托</td></tr><tr><td>闪兑</td><td>两种资产之间按当前价格直接兑换，无需挂单</td></tr><tr><td>秒合约</td><td>短周期涨跌方向判断，到期按结果结算</td></tr><tr><td>U 本位永续合约</td><td>带杠杆的多空双向交易，支持止盈止损与强制平仓</td></tr><tr><td>TradFi 传统金融</td><td>外汇、商品、股票、指数、港股等标的的行情与交易</td></tr><tr><td>跟单交易</td><td>带单员发码、用户凭码一键跟投，详见<a href="/CoinExchange/zh/guide/follow">跟单交易</a></td></tr></tbody></table><h2 id="理财与增值" tabindex="-1">理财与增值 <a class="header-anchor" href="#理财与增值" aria-label="Permalink to &quot;理财与增值&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>说明</th></tr></thead><tbody><tr><td>理财</td><td>按周期计息的资产管理产品</td></tr><tr><td>质押挖矿</td><td>锁仓获取收益</td></tr><tr><td>助力贷</td><td>借贷类玩法</td></tr><tr><td>申购（打新）</td><td>新币认购，含筹备、订阅、审批、进行、发行等状态流转</td></tr><tr><td>自发币与做市</td><td>平台可以发行自己的币种，并绑定给指定的做市商账号管理；自发币还可作为手续费抵扣币，详见<a href="/CoinExchange/zh/guide/market-maker">做市商端</a></td></tr></tbody></table><h2 id="资金" tabindex="-1">资金 <a class="header-anchor" href="#资金" aria-label="Permalink to &quot;资金&quot;">​</a></h2><ul><li><strong>充值</strong>：数字资产充值，用户拥有专属收款地址，链上到账后自动入账</li><li><strong>提现</strong>：提现申请与后台审核，支持提现通道与限额配置</li><li><strong>划转</strong>：账户内不同资金账户之间的资产划转</li><li><strong>资金流水</strong>：所有资金变动的完整记录</li></ul><p>详见<a href="/CoinExchange/zh/guide/finance">充值与提现</a>。</p><h2 id="用户与运营" tabindex="-1">用户与运营 <a class="header-anchor" href="#用户与运营" aria-label="Permalink to &quot;用户与运营&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>说明</th></tr></thead><tbody><tr><td>用户管理</td><td>用户资料、账户状态、信用分</td></tr><tr><td>实名认证（KYC）</td><td>初级/高级认证，含后台审核</td></tr><tr><td>VIP 等级</td><td>等级门槛与权益说明均可在后台配置</td></tr><tr><td>推广与代理</td><td>邀请码、邀请关系、佣金</td></tr><tr><td>地域限制</td><td>按地区限制访问</td></tr><tr><td>帮助中心与公告</td><td>内容由后台维护</td></tr><tr><td>站内信</td><td>后台向指定用户或全站发送消息，用户在 App / 网页的消息中心查看</td></tr><tr><td>开放接口（API Key）</td><td>为外部系统签发调用行情与开放接口的凭据，可设频率限制与 IP 白名单</td></tr><tr><td>在线客服</td><td>用户在 App / 手机网页内直接聊天，客服在 Telegram 话题群接待，一人一会话、图文实时互通，详见<a href="/CoinExchange/zh/guide/customer-service">在线客服</a></td></tr></tbody></table><h2 id="多语言" tabindex="-1">多语言 <a class="header-anchor" href="#多语言" aria-label="Permalink to &quot;多语言&quot;">​</a></h2><p>用户端支持简体中文、繁体中文、英语、日语、韩语、越南语、泰语共 <strong>7 种语言</strong>，由后台的语言字典控制启用范围。</p><h2 id="移动端-app" tabindex="-1">移动端 App <a class="header-anchor" href="#移动端-app" aria-label="Permalink to &quot;移动端 App&quot;">​</a></h2><p><strong>原生双端 App（Android / iOS）</strong>，非网页套壳。功能与 H5 端对齐，并支持<strong>自动检测新版本并提示更新</strong>；安卓端可在 App 内直接完成下载与安装。详见<a href="/CoinExchange/zh/app/overview">移动端 App</a>。</p><hr><div class="tip custom-block"><p class="custom-block-title">说明</p><p>本页只列已实现的功能。如需了解某个功能的具体业务规则（如费率、结算口径、风控参数），这些均由运营在后台配置，请以贵方后台的实际配置为准。</p></div>',17)])])}const b=a(o,[["render",h]]);export{u as __pageData,b as default};
